// Play application entrypoint registering sketchpad apps and rendering the root.
// Entrypoint MUST register all app configs before rendering the Sketchpad component.

import { Sketchpad, appRegistry, designConfig, docsConfig, feedbackConfig, homeConfig, kitConfig, qualityConfig, typeConfig } from "@semio-tech/compose-sketchpad";
import { createIndexeddbPersistenceFactory } from "@compose/studio";
