export const SketchpadScopeProvider = (props: {
  id?: string;
  store?: SketchpadStore;
  kitStore?: KitStore;
  remote?: RemoteProviders;
  persistenceFactory?: PersistenceFactory;
  temporaryKitStoreFactory?: SketchpadKitStoreFactory;
  folderKitStoreFactory?: SketchpadKitStoreFactory;
  fileKitStoreFactory?: SketchpadKitStoreFactory;
  remoteKitStoreFactory?: SketchpadKitStoreFactory;
  onWindowEvents?: WindowEvents;
  initialState?: ExtendedInitialState;
  importKitUrls?: string[];
  children: React.ReactNode;
}) => {
  const id = useMemo(() => props.id || guid(), [props.id]);
  const [configsReady, setConfigsReady] = useState(false);

  useEffect(() => {
    loadAppConfigs().then(() => setConfigsReady(true));
  }, []);

  if (!stores.has(id)) {
    const store =
      props.store ?? new SketchpadStore(id, props?.remote, props?.initialState, props?.persistenceFactory, props?.kitStore, props?.temporaryKitStoreFactory, props?.folderKitStoreFactory, props?.fileKitStoreFactory, props?.remoteKitStoreFactory);
    stores.set(id, store);

    const actor = createSketchpadActor({ id, initialState: mergeSketchpadState(mergeSketchpadState(store.snapshot(), readSketchpadStateFromLocalStorage(id)), toSketchpadInitialState(props?.initialState)) });
    actor.start();
    actors.set(id, actor);
    store.setActor(actor);

    if (typeof window !== "undefined") {
      (window as any).__COMPOSE_STORE__ = store;
      (window as any).__COMPOSE_ACTOR__ = actor;
      (window as any).__piecesMetadata = piecesMetadata;
    }
  }

  const actor = actors.get(id)!;
  const store = stores.get(id)!;

  useEffect(() => {
    if (!configsReady || !props.importKitUrls || props.importKitUrls.length === 0) return;

    const doImportKits = async () => {
      for (const url of props.importKitUrls!) {
        try {
          const { kit } = await importKit(url);

          await store.execute("compose.sketchpad.createKit", "compose.sketchpad.importKitUrls", kit, false, false);
        } catch (error) {
          console.error(`[Sketchpad] Failed to auto-import kit from ${url}:`, error);
        }
      }
    };

    doImportKits();

const routerContent = (
  <GlobalNavigationBridge>
    <SketchpadScopeProvider
      id={id}
      store={store}
      kitStore={kitStore}
      remote={remote}
      persistenceFactory={persistenceFactory}
      temporaryKitStoreFactory={temporaryKitStoreFactory}
      folderKitStoreFactory={folderKitStoreFactory}
      fileKitStoreFactory={fileKitStoreFactory}
      remoteKitStoreFactory={remoteKitStoreFactory}
      onWindowEvents={onWindowEvents}
      initialState={initialState}
      importKitUrls={importKitUrls}
    >
      <SketchpadInteractionBridge>
        <OriginProvider>
