  const vscodeApi = (window as any).__COMPOSE_VSCODE_API__;
  return async (kit) => {
    const adapter: KitJsonFileAdapter = {
      read: async () => JSON.stringify(kit),
      write: async (json: string) => {
        vscodeApi.postMessage({ kind: "kit.save", content: json });
      },
