// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖sketchpadcomponents🪨sketchpad](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Sketchpad%20Components/d/i/Sketchpad)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖sketchpadcomponents🪨sketchpad](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Sketchpad%20Components/d/i/Sketchpad)
 * Sketchpad holds the data fields for a Sketchpad record.
 **/
const Sketchpad = ({
  id,
  store,
  kitStore,
  remote,
  persistenceFactory,
  temporaryKitStoreFactory,
  folderKitStoreFactory,
  fileKitStoreFactory,
  remoteKitStoreFactory,
  onWindowEvents,
  initialState,
  importKitUrls,
  embedded,
}: {
  id?: string;
  store?: SketchpadStore;
  kitStore?: KitStore;
  remote?: RemoteProviders;
  persistenceFactory?: PersistenceFactory;
  temporaryKitStoreFactory?: SketchpadKitStoreFactory;
  folderKitStoreFactory?: SketchpadKitStoreFactory;
  fileKitStoreFactory?: SketchpadKitStoreFactory;
  remoteKitStoreFactory?: SketchpadKitStoreFactory;
  onWindowEvents?: WindowEvents;
  initialState?: ExtendedInitialState;
  importKitUrls?: string[];
  embedded?: boolean;
}): React.JSX.Element => {
  const initialEntries = useMemo(() => {
    if (!embedded) return undefined;
    if (typeof window !== "undefined" && window.location) {
      return [window.location.pathname + window.location.search];
    }
    return ["/"];
  }, [embedded]);

  const routerContent = (
    <GlobalNavigationBridge>
      <SketchpadScopeProvider
        id={id}
        store={store}
        kitStore={kitStore}
        remote={remote}
        persistenceFactory={persistenceFactory}
        temporaryKitStoreFactory={temporaryKitStoreFactory}
        folderKitStoreFactory={folderKitStoreFactory}
        fileKitStoreFactory={fileKitStoreFactory}
        remoteKitStoreFactory={remoteKitStoreFactory}
        onWindowEvents={onWindowEvents}
        initialState={initialState}
        importKitUrls={importKitUrls}
      >
        <SketchpadInteractionBridge>
          <OriginProvider>
            <FocusProvider>
              <PanelSectionProvider>
                <SidePanelTabProvider>
                  <FooterItemProvider>
                    <DragDropProvider>
                      <SketchpadContent />
                    </DragDropProvider>
                  </FooterItemProvider>
                </SidePanelTabProvider>
              </PanelSectionProvider>
            </FocusProvider>
          </OriginProvider>
        </SketchpadInteractionBridge>
      </SketchpadScopeProvider>
    </GlobalNavigationBridge>
  );

  if (embedded) {
    return (
      <MemoryRouter initialEntries={initialEntries} unstable_useTransitions={false}>
        {routerContent}
      </MemoryRouter>
    );
  }

  return <BrowserRouter unstable_useTransitions={false}>{routerContent}</BrowserRouter>;
};

